CREATE TYPE "GoodsCollectionStatus" AS ENUM ('PENDING_CONFIRMATION','CONFIRMED','REJECTED','RELEASED','CANCELLED','EXPIRED');
CREATE TABLE "goods_collection_policies" ("id" UUID NOT NULL,"version" TEXT NOT NULL,"configuration" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "goods_collection_policies_pkey" PRIMARY KEY ("id"));
CREATE TABLE "goods_collections" ("id" UUID NOT NULL,"reference" TEXT NOT NULL,"studentId" UUID NOT NULL,"semesterId" UUID NOT NULL,"clerkUserId" UUID NOT NULL,"releasedByUserId" UUID,"status" "GoodsCollectionStatus" NOT NULL DEFAULT 'PENDING_CONFIRMATION',"eligibilitySnapshot" JSONB NOT NULL,"policyVersion" TEXT NOT NULL,"confirmationRequestId" UUID,"reservedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"confirmedAt" TIMESTAMP(3),"rejectedAt" TIMESTAMP(3),"releasedAt" TIMESTAMP(3),"cancelledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "goods_collections_pkey" PRIMARY KEY ("id"));
CREATE TABLE "goods_collection_lines" ("id" UUID NOT NULL,"collectionId" UUID NOT NULL,"batchId" UUID NOT NULL,"reservationId" UUID NOT NULL,"categoryCode" TEXT NOT NULL,"itemName" TEXT NOT NULL,"unit" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "goods_collection_lines_pkey" PRIMARY KEY ("id"),CONSTRAINT "goods_collection_lines_quantity_check" CHECK ("quantity" > 0));
CREATE UNIQUE INDEX "goods_collection_policies_version_key" ON "goods_collection_policies"("version");
CREATE INDEX "goods_collection_policies_active_createdAt_idx" ON "goods_collection_policies"("active","createdAt");
CREATE UNIQUE INDEX "goods_collections_reference_key" ON "goods_collections"("reference");
CREATE UNIQUE INDEX "goods_collections_confirmationRequestId_key" ON "goods_collections"("confirmationRequestId");
CREATE UNIQUE INDEX "goods_collections_one_open_per_student" ON "goods_collections"("studentId") WHERE "status" IN ('PENDING_CONFIRMATION','CONFIRMED');
CREATE INDEX "goods_collections_studentId_createdAt_idx" ON "goods_collections"("studentId","createdAt");
CREATE INDEX "goods_collections_status_reservedAt_idx" ON "goods_collections"("status","reservedAt");
CREATE UNIQUE INDEX "goods_collection_lines_reservationId_key" ON "goods_collection_lines"("reservationId");
CREATE UNIQUE INDEX "goods_collection_lines_collectionId_batchId_key" ON "goods_collection_lines"("collectionId","batchId");
CREATE INDEX "goods_collection_lines_categoryCode_idx" ON "goods_collection_lines"("categoryCode");
ALTER TABLE "goods_collections" ADD CONSTRAINT "goods_collections_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "students"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "goods_collections" ADD CONSTRAINT "goods_collections_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "academic_semesters"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "goods_collections" ADD CONSTRAINT "goods_collections_clerkUserId_fkey" FOREIGN KEY ("clerkUserId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "goods_collections" ADD CONSTRAINT "goods_collections_releasedByUserId_fkey" FOREIGN KEY ("releasedByUserId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "goods_collection_lines" ADD CONSTRAINT "goods_collection_lines_collectionId_fkey" FOREIGN KEY ("collectionId") REFERENCES "goods_collections"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "goods_collection_lines" ADD CONSTRAINT "goods_collection_lines_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "inventory_batches"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "goods_collection_lines" ADD CONSTRAINT "goods_collection_lines_reservationId_fkey" FOREIGN KEY ("reservationId") REFERENCES "inventory_reservations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
